mapper.select:
        select
        foodIngredients.*,ingredients.name,ingredients.type
        from food_ingredients foodIngredients
        left join ingredients ingredients on foodIngredients.ingredients_id = ingredients.id
		left join foods foods on foodIngredients.food_id = foods.id

            and foodIngredients.id = #{id}
            and foodIngredients.food_id = #{foodId}
            and foodIngredients.ingredients_id = #{ingredientsId}
            and foodIngredients.create_time = #{createTime}
            and ingredients.type = #{type}
            and ingredients.name like concat('%',#{name},'%')


            limit #{current},#{pageSize}

        select count(*) from food_ingredients foodIngredients
        left join ingredients ingredients on foodIngredients.ingredients_id = ingredients.id
		left join foods foods on foodIngredients.food_id = foods.id

            and foodIngredients.id = #{id}
            and foodIngredients.food_id = #{foodId}
            and foodIngredients.ingredients_id = #{ingredientsId}
            and foodIngredients.create_time = #{createTime}
            and ingredients.type = #{type}
            and ingredients.name like concat('%',#{name},'%')
